import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold or takes them off it; holding one already held, or releasing one not held, is refused. */
public class HoldPerson {
    public void hold(@Val Person person, @Val Hold hold, PersonRepository people, Out<Person> held)
            throws InvalidPersonException {
        if (!people.hold(person.sheetId(), person.id(), hold.held())) {
            throw new InvalidPersonException(hold.held() ? "The person is already on hold" : "The person is not on hold");
        }
        held.set(new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                person.retiredFrom(), hold.held()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date; a retirement given no date is from the sheet's today. */
public class RetirePerson {
    public void retire(@Val Person person, @Val Retirement retirement, SheetRepository sheets, PersonRepository people,
            Out<Person> retired) {
        LocalDate from = retirement.from() != null ? retirement.from() : sheets.today(person.sheetId());
        people.retire(person.sheetId(), person.id(), from);
        retired.set(new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(), from.toString(),
                person.held()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id; one not on the sheet is a 404. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository people, Out<Person> person) throws PersonNotFoundException {
        Person found;
        try {
            found = people.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new PersonNotFoundException("No person " + personId);
        }
        person.set(found);
    }
}
